/**
 * The poster (PRD §8.7): generated from the same layout the engine builds
 * from, committed, and regenerated by the build, so it cannot drift from
 * the registry. The test renders it again and compares with the committed
 * file byte for byte, and checks what it must and must not contain.
 */
import fs from 'node:fs';
import path from 'node:path';
import { describe, expect, it } from 'vitest';
import { LAYOUT } from '@/world/placement/layout.generated';
import { renderPoster } from '../../scripts/world/render-poster.mjs';

const FILE = path.resolve(__dirname, '../../public/world/poster-far.svg');

describe('the poster', () => {
  const svg = renderPoster(LAYOUT);
  it('is the committed file, byte for byte', () => {
    expect(fs.readFileSync(FILE, 'utf8')).toBe(svg);
  });
  it('draws every block and region label, and the dashed raw-export road', () => {
    expect((svg.match(/<polygon /g) ?? []).length).toBeGreaterThanOrEqual(LAYOUT.blocks.length * 3);
    for (const l of LAYOUT.labels.filter((x) => x.level === 'far')) expect(svg).toContain(l.text.toUpperCase());
    expect(svg).toContain('stroke-dasharray');
  });
  it('carries no figure, no company and no status: the world at rest', () => {
    expect(svg).not.toMatch(/Published|No model yet|INTP|SMGR|PTBA|ITMG/);
    expect(svg).toMatch(/aria-label="The industrial estate at the far view/);
  });
  it('is small enough to be the first paint', () => {
    expect(svg.length).toBeLessThan(400 * 1024);
  });
});
